(function(){'use strict';
/* Compliance Database generator — jahdb-compliance-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-CMP-';
var SRC='public';
var RECORD_KIND='compliance record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"Regulatory compliance means operating within the laws, regulations, and standards that govern an industry — the discipline of proving you follow the rules.","examples":["A hospital trains staff on HIPAA, encrypts patient records, and audits access logs to protect health data.","A public company documents financial controls and has auditors test them for SOX compliance."],"history":["Modern compliance grew with 20th-century regulation; corporate compliance programs became standard after 1990s sentencing guidelines rewarded them.","The 2000s scandals (Enron) and 2010s privacy laws (GDPR) made compliance a board-level function."],"points":["Compliance has three pillars: know the rules, implement controls that satisfy them, and prove it with evidence.","It spans industries: finance, healthcare, privacy, environment, workplace safety — each with its own regulators.","Non-compliance costs: fines, lawsuits, lost licenses, and reputational damage far exceeding program costs.","Effective programs are risk-based: focus effort where the risk and regulatory attention are highest."],"qa":[["Compliance vs. ethics?","Compliance follows the letter of the rules; ethics follows their spirit — strong programs need both."],["Who owns compliance?","Everyone, but led by a compliance officer with board access and independence from business pressure."],["What is a compliance program?","The policies, training, monitoring, and reporting that keep an organization within the rules."]],"title":"What Is Regulatory Compliance","uses":["Avoiding fines, sanctions, and license loss.","Building customer and regulator trust.","Making rule-following systematic rather than accidental."]},{"brief":"The GDPR is the EU's comprehensive data-protection law — giving individuals rights over their personal data and imposing strict duties on organizations that process it.","examples":["A website shows a consent banner before setting tracking cookies for EU visitors.","A user requests all their data from a service and receives a full export within a month."],"history":["The GDPR replaced the 1995 Data Protection Directive, taking effect May 25, 2018.","Its fines — up to 4% of global revenue — and extraterritorial reach made it the world's privacy benchmark."],"points":["Core principles: lawfulness, purpose limitation, data minimization, accuracy, storage limitation, and security.","Individual rights: access, correction, deletion, portability, objection, and explanation of automated decisions.","Lawful bases: consent, contract, legal obligation, vital interests, public task, or legitimate interests.","Breach notification within 72 hours to regulators; fines up to 4% of global annual turnover."],"qa":[["Does GDPR apply outside the EU?","Yes — to any organization processing EU residents' data, regardless of where the company sits."],["What is a Data Protection Officer?","A designated expert overseeing GDPR compliance, required for large-scale processing."],["What is the right to be forgotten?","The right to have personal data erased when it's no longer needed or consent is withdrawn."]],"title":"GDPR (General Data Protection Regulation)","uses":["Protecting EU residents' personal data across the globe.","Forcing organizations to inventory and justify their data processing.","Setting the template for privacy laws worldwide."]},{"brief":"HIPAA is the U.S. law protecting health information — setting privacy, security, and breach-notification rules for healthcare providers, plans, and their vendors.","examples":["A clinic encrypts patient records and trains staff never to discuss cases in public areas.","A cloud vendor signs a Business Associate Agreement before hosting hospital data."],"history":["HIPAA passed in 1996; its Privacy and Security Rules took effect in the 2000s.","HITECH (2009) strengthened enforcement and extended duties to business associates."],"points":["The Privacy Rule limits who may see protected health information and for what purposes.","The Security Rule requires administrative, physical, and technical safeguards for electronic health data.","Business Associates (vendors handling PHI) must sign agreements and follow the same rules.","Breach notification: inform affected individuals, regulators, and (for large breaches) the media."],"qa":[["What is PHI?","Protected Health Information: any individually identifiable health data — records, bills, even appointment lists."],["Does HIPAA apply to everyone?","No — only covered entities (providers, plans, clearinghouses) and their business associates."],["What are the penalties?","Tiered civil fines up to $1.5M+ per violation category annually, plus criminal charges for willful misuse."]],"title":"HIPAA","uses":["Protecting patient privacy in healthcare.","Securing electronic health records.","Holding vendors to the same standards as providers."]},{"brief":"PCI DSS is the payment-card industry's security standard — the rules any organization handling card data must follow to prevent breaches.","examples":["A retailer segments its card-processing network and never stores full magnetic-stripe data.","A SaaS company uses tokenization so card numbers never touch its servers."],"history":["Card brands created PCI DSS in 2004 after waves of retail breaches.","Version 4.0 (2022) modernized requirements for cloud and agile development."],"points":["Twelve requirement families: firewalls, no defaults, protect stored data, encrypt in transit, anti-malware, secure development, access control, authentication, physical security, logging, testing, and policies.","Scope reduction is the strategy: the less card data you touch, the less PCI applies — tokenize and outsource.","Compliance is validated annually by assessments (SAQ or QSA audit) plus quarterly network scans.","Non-compliance risks fines from card brands and loss of card-processing privileges — an existential threat to merchants."],"qa":[["Who must comply with PCI DSS?","Any organization storing, processing, or transmitting card data — from global retailers to small shops."],["What is tokenization?","Replacing card numbers with random tokens — the real data lives only with the payment processor."],["What is scope?","The systems and people touching card data — shrinking scope shrinks compliance burden."]],"title":"PCI DSS","uses":["Preventing card-data breaches at merchants.","Enabling safe e-commerce and retail payments.","Reducing risk through tokenization and scope control."]},{"brief":"The Sarbanes-Oxley Act (SOX) reformed U.S. corporate financial reporting after Enron — requiring executive accountability and tested internal controls.","examples":["A CEO and CFO personally certify quarterly financial reports under penalty of law.","Auditors test whether the company's revenue-recognition controls actually work."],"history":["SOX passed in 2002 after Enron and WorldCom collapses destroyed investor trust.","Section 404's internal-control audits became the most expensive — and debated — provision."],"points":["Sections 302 and 906: executives certify financial reports personally — false certification is criminal.","Section 404: management assesses internal controls over financial reporting; auditors attest to it.","Coverage: U.S. public companies and their key subsidiaries, including foreign filers.","Costs are significant but the goal — reliable financial statements — underpins market trust."],"qa":[["What are internal controls?","Processes ensuring financial reports are accurate: approvals, reconciliations, segregation of duties."],["Does SOX apply to private companies?","Not directly, but many adopt its practices for investor confidence and IPO readiness."],["What is segregation of duties?","Splitting responsibilities so no one person controls a whole financial process — preventing fraud."]],"title":"Sarbanes-Oxley (SOX)","uses":["Restoring investor trust in financial reporting.","Preventing executive fraud through personal accountability.","Standardizing internal controls at public companies."]},{"brief":"ISO 27001 is the international standard for information security management systems — the certifiable framework for managing security systematically.","examples":["A SaaS company earns ISO 27001 certification to win enterprise contracts.","Annex A controls guide its access management, encryption, and incident response."],"history":["Born from British Standard BS 7799 (1990s), ISO 27001 became the global ISMS standard in 2005.","The 2022 revision modernized controls for cloud and remote work."],"points":["The ISMS: a management system of policies, risk assessment, controls, and continual improvement — not just technology.","Annex A lists 93 controls across organizational, people, physical, and technological themes.","Certification comes from accredited auditors in a multi-stage audit; it must be maintained, not just earned.","Risk assessment drives control selection: treat, tolerate, transfer, or terminate each risk."],"qa":[["What is an ISMS?","Information Security Management System: the organized way security is governed, not a product."],["How long does certification take?","Typically 6-12 months for a first certification, depending on size and maturity."],["ISO 27001 vs. SOC 2?","ISO is a certifiable international standard; SOC 2 is a U.S. attestation report — many companies hold both."]],"title":"ISO 27001","uses":["Proving systematic security management to customers.","Winning enterprise and government contracts.","Organizing security around risk rather than tools."]},{"brief":"SOC 2 is the American attestation report on a service organization's controls — the trust credential SaaS buyers demand.","examples":["A startup completes SOC 2 Type II to unblock enterprise sales.","The report details how access controls and change management operated over six months."],"history":["SOC 2 grew from SAS 70 audits; the AICPA formalized it for the cloud era in the 2010s.","Type II reports (operating effectiveness over time) became the expected standard."],"points":["Five trust criteria: Security (required), plus Availability, Processing Integrity, Confidentiality, Privacy.","Type I: controls designed well at a point in time. Type II: operated effectively over 6-12 months.","Audited by licensed CPAs; the report is shared under NDA with customers and prospects.","SOC 2 is a report, not a certification — read the actual report, not just the logo."],"qa":[["Type I vs. Type II?","Type I checks design at a moment; Type II tests operation over months — buyers want Type II."],["Who can issue SOC 2?","Licensed CPA firms following AICPA standards."],["How long does it take?","Readiness plus a 6-12 month observation window for Type II — plan a year."]],"title":"SOC 2","uses":["Unblocking enterprise SaaS sales.","Proving control operation to customers under NDA.","Complementing ISO 27001 for U.S. buyers."]},{"brief":"The CCPA/CPRA gives California residents privacy rights — to know, delete, and opt out of the sale of personal information — with enforcement teeth.","examples":["A website adds a 'Do Not Sell My Personal Information' link for California visitors.","A consumer requests deletion and the company must erase their data across systems."],"history":["The CCPA took effect in 2020; the CPRA (2020 ballot measure) strengthened it from 2023.","It sparked a wave of U.S. state privacy laws following its template."],"points":["Rights: know what's collected, delete it, opt out of sale/sharing, and non-discrimination for exercising rights.","Applies to businesses meeting revenue or data-volume thresholds doing business in California.","The CPRA added sensitive-data rights, data minimization, and a dedicated enforcement agency.","Penalties up to $7,500 per intentional violation — breaches enabling lawsuits multiply fast."],"qa":[["CCPA vs. GDPR?","Similar rights, different mechanics: CCPA centers on opt-out of sale; GDPR on consent and lawful bases."],["What is 'sale' under CCPA?","Broadly defined — including sharing for cross-context behavioral advertising, not just money changing hands."],["Does it apply to my small business?","Only if you meet thresholds (revenue, data volume) — but other state laws may still apply."]],"title":"CCPA/CPRA (California Privacy)","uses":["Giving Californians control over personal data.","Forcing data inventories and deletion capabilities.","Seeding U.S. state privacy legislation."]},{"brief":"FERPA is the U.S. law protecting student education records — giving parents (and adult students) rights over school-held data.","examples":["A university can't release a student's grades to parents without consent once the student turns 18.","A school district vets ed-tech vendors' data practices before adoption."],"history":["FERPA passed in 1974 amid Watergate-era privacy concerns.","Digital records and ed-tech in the 2010s tested its school-official exceptions."],"points":["Rights transfer from parent to student at 18 or postsecondary enrollment.","Schools may disclose without consent to 'school officials' with legitimate educational interests — vendors included under strict terms.","Directory information (name, enrollment) may be shared unless the student opts out.","Violations risk loss of federal education funding — the enforcement lever."],"qa":[["What are education records?","Records directly related to a student maintained by the school — grades, discipline, health files at school."],["Can parents see college grades?","Not without the student's consent once FERPA rights transfer — a surprise to many families."],["How do ed-tech vendors comply?","As school officials under contract: using data only for the educational purpose, with safeguards."]],"title":"FERPA","uses":["Protecting student records from unauthorized disclosure.","Governing ed-tech vendor data practices.","Balancing parent rights with student privacy."]},{"brief":"COPPA is the U.S. law protecting children's online privacy — requiring verifiable parental consent before collecting data from kids under 13.","examples":["A kids' game asks for a parent's email and consent before creating a child account.","A video platform pays a record fine for collecting children's data without consent."],"history":["COPPA took effect in 2000; the FTC's 2013 update covered persistent identifiers like cookies.","Record fines in the 2010s-2020s targeted platforms popular with children."],"points":["Covered: operators of sites/services directed at children under 13, or with actual knowledge of child users.","Requires clear privacy policies and verifiable parental consent before collecting personal info.","Limits: collect only what's needed, keep it only as long as needed, protect it.","FTC enforcement has produced nine-figure fines — the cost of treating kids' data casually."],"qa":[["What is verifiable parental consent?","A method reasonably ensuring the consenter is the parent — email plus, credit card, video call, or similar."],["Does COPPA cover teens?","No — under 13 only; proposed updates would extend protections, but that's not current law."],["What counts as personal info?","Names, addresses, and also persistent identifiers — cookies, device IDs — that track children."]],"title":"COPPA","uses":["Protecting children's data from commercial exploitation.","Forcing age-aware design in kids' products.","Punishing platforms that track children without consent."]},{"brief":"The NIST Cybersecurity Framework organizes cybersecurity into five functions — Identify, Protect, Detect, Respond, Recover — the common language of cyber risk management.","examples":["A manufacturer maps its controls to the framework to find gaps before an audit.","A board reviews the company's maturity across the five functions quarterly."],"history":["NIST released the framework in 2014 after a presidential executive order; version 2.0 (2024) added governance.","It became the de facto baseline referenced by regulators worldwide."],"points":["Five functions: Identify (know assets/risks), Protect (safeguards), Detect (monitoring), Respond (incidents), Recover (restoration).","Implementation tiers measure maturity from partial to adaptive — progress, not perfection.","Profiles customize the framework: current state versus target state, with a roadmap between.","It's voluntary but mighty: contracts, insurance, and regulators increasingly expect it."],"qa":[["Is the framework a certification?","No — it's a voluntary risk-management tool, though assessments against it are common."],["What changed in 2.0?","A new Govern function and broader scope beyond critical infrastructure."],["Who uses it?","Everyone from small businesses to federal agencies — its flexibility is the point."]],"title":"NIST Cybersecurity Framework","uses":["Organizing cybersecurity programs around risk.","Communicating cyber posture to boards in plain language.","Baselining controls before deeper audits."]},{"brief":"FedRAMP is the U.S. program authorizing cloud products for federal use — a rigorous standardized security assessment that unlocks government markets.","examples":["A SaaS company earns FedRAMP authorization to sell to federal agencies.","An agency reuses an existing authorization instead of running its own assessment."],"history":["FedRAMP launched in 2011 to standardize cloud security for government.","Continuous monitoring requirements keep authorizations honest over time."],"points":["Baselines (Low/Moderate/High) set control requirements by data sensitivity.","Paths: agency authorization or the Joint Authorization Board's provisional approval.","The 'do once, use many' model: one assessment serves many agencies.","Costs are high (often $1M+) but so is the federal market — plan carefully."],"qa":[["How long does authorization take?","Typically 12-18 months for a first authorization."],["What is continuous monitoring?","Ongoing evidence — monthly scans, annual assessments — proving controls still work."],["Does FedRAMP help commercial sales?","Yes — enterprises treat it as a strong security signal."]],"title":"FedRAMP","uses":["Selling cloud products to the U.S. government.","Proving high-assurance security to regulated buyers.","Standardizing assessments across agencies."]},{"brief":"Anti-money-laundering (AML) and Know Your Customer (KYC) rules require financial institutions to verify identities and report suspicious activity.","examples":["A bank verifies a new customer's ID and screens them against sanctions lists.","An algorithm flags structuring — deposits just under reporting thresholds — for investigation."],"history":["The Bank Secrecy Act (1970) started U.S. AML; the Patriot Act (2001) expanded it dramatically.","Global FATF standards spread AML duties to crypto and other sectors in the 2010s-2020s."],"points":["KYC: verify identity at onboarding and monitor throughout the relationship.","Suspicious Activity Reports go to regulators; tipping off the customer is illegal.","Risk-based programs focus scrutiny where laundering risk is highest.","Penalties reach billions — AML failures are among the costliest compliance lapses."],"qa":[["What is structuring?","Splitting transactions to evade reporting thresholds — a classic laundering red flag."],["Who must comply?","Banks, money services, and increasingly crypto, real estate, and other FATF-covered sectors."],["What is the FATF?","The Financial Action Task Force — the intergovernmental body setting global AML standards."]],"title":"AML and KYC","uses":["Keeping criminal money out of the financial system.","Meeting regulatory duties in banking and fintech.","Screening customers against sanctions and watchlists."]},{"brief":"The FCPA prohibits U.S. companies from bribing foreign officials — with accounting provisions that punish sloppy books even without proven bribes.","examples":["A company discloses improper payments by a foreign subsidiary and cooperates with investigators.","Gifts, travel, and entertainment for officials get pre-approval under a strict policy."],"history":["The FCPA passed in 1977 after Watergate-era bribery scandals.","Enforcement surged in the 2000s-2010s with multi-hundred-million-dollar settlements."],"points":["Two prongs: anti-bribery (no corrupt payments to foreign officials) and accounting (accurate books, internal controls).","Applies broadly: U.S. companies, issuers, and anyone acting on U.S. soil.","M&A due diligence must uncover target companies' bribery exposure — successor liability is real.","Effective compliance programs — training, reporting, discipline — earn cooperation credit."],"qa":[["What is a facilitating payment?","Small payments to expedite routine acts — narrowly excepted but banned by most company policies."],["Does it cover private bribery?","No — foreign officials only; commercial bribery is covered by other laws."],["What triggers investigations?","Whistleblowers, media, competitors, and voluntary disclosures."]],"title":"FCPA (Foreign Corrupt Practices Act)","uses":["Prohibiting bribery in international business.","Forcing accurate books that can't hide payoffs.","Diligencing acquisitions for corruption exposure."]},{"brief":"OSHA sets and enforces U.S. workplace safety standards — employers must provide workplaces free of recognized hazards.","examples":["A construction firm implements fall protection and trench safety per OSHA standards.","A warehouse addresses ergonomic injuries after an OSHA inspection."],"history":["The OSH Act created OSHA in 1970; workplace deaths have fallen dramatically since.","Enforcement combines standards, inspections, and whistleblower protections."],"points":["The General Duty Clause covers recognized hazards even without a specific standard.","Employers must train workers on hazards, provide PPE, and keep injury records.","Workers can file confidential complaints triggering inspections; retaliation is illegal.","Penalties per violation reach six figures for willful or repeated offenses."],"qa":[["What triggers an OSHA inspection?","Complaints, referrals, severe injuries, and programmed inspections of hazardous industries."],["What is the General Duty Clause?","The requirement to keep workplaces free of recognized serious hazards — the catch-all standard."],["Do small businesses comply?","Yes — most standards apply regardless of size, with some recordkeeping exceptions."]],"title":"OSHA (Workplace Safety)","uses":["Preventing workplace injuries and deaths.","Enforcing safety standards through inspections.","Protecting workers who report hazards."]},{"brief":"EPA environmental compliance governs air, water, waste, and chemicals — permits, reporting, and cleanup duties for regulated activities.","examples":["A factory operates under an air-emissions permit with continuous monitoring.","A company reports chemical inventories annually under community right-to-know laws."],"history":["The EPA was founded in 1970; the Clean Air and Clean Water Acts built the modern framework.","Superfund (1980) made polluters pay for historic contamination cleanup."],"points":["Media-specific laws: air, water, waste, toxics, and drinking water each have their own regime.","Permits authorize emissions within limits; monitoring and reporting prove compliance.","Strict liability for cleanup: current and past owners can all pay for contamination.","States often run delegated programs with standards stricter than federal minimums."],"qa":[["What is a permit?","Government authorization to emit pollutants within set limits, with monitoring conditions."],["What is Superfund liability?","Strict, joint liability for cleaning contaminated sites — even for past owners."],["Do small businesses comply?","Yes where thresholds trigger — waste, chemicals, and emissions rules scale by activity."]],"title":"EPA Environmental Compliance","uses":["Controlling industrial pollution within legal limits.","Cleaning up contaminated sites.","Informing communities about chemical risks."]},{"brief":"FDA regulation governs food, drugs, devices, and more — premarket approvals, manufacturing standards, and labeling truth.","examples":["A new drug needs clinical trials and FDA approval before marketing.","A device maker follows Quality System Regulation in manufacturing."],"history":["The 1906 Pure Food and Drug Act started it; the 1938 and 1962 amendments built modern premarket power.","Risk-based frameworks now span from Class I bandages to Class III implants."],"points":["Drugs: prove safety and efficacy through trials. Devices: classification determines the approval path.","cGMP (current Good Manufacturing Practice) governs how products are made — quality built in.","Labeling must be truthful and not misleading — a major enforcement area.","Post-market surveillance continues after approval: adverse events, inspections, recalls."],"qa":[["What is 510(k)?","The device pathway showing substantial equivalence to a marketed predicate — faster than full approval."],["What is cGMP?","The manufacturing quality system: documented, controlled, validated processes."],["When does FDA recall?","Voluntary by companies or mandated — for products violating the law or endangering health."]],"title":"FDA Regulation","uses":["Ensuring drugs and devices are safe and effective.","Policing manufacturing quality.","Protecting consumers from misbranded products."]},{"brief":"The FTC polices unfair and deceptive practices — advertising truth, data security, and antitrust — across most of the U.S. economy.","examples":["The FTC fines a company for misleading 'free trial' billing practices.","A data-broker settlement requires biennial privacy audits for 20 years."],"history":["The FTC was created in 1914; its consumer-protection mission expanded with the digital economy.","Privacy enforcement grew through Section 5 actions against broken promises."],"points":["Section 5 prohibits unfair or deceptive acts — the flexible basis for privacy and ad cases.","Advertising must be truthful, substantiated, and disclose material connections (endorsements).","Data security is enforced as a promise: claiming 'secure' while negligent invites action.","Remedies include fines, 20-year consent decrees, and mandated compliance programs."],"qa":[["What is a consent decree?","A settlement imposing long-term compliance duties — audits, reporting — under FTC oversight."],["Does the FTC write privacy law?","It enforces through cases rather than rules, though rulemaking has expanded."],["What is substantiation?","Advertisers must have evidence for claims before making them — especially health claims."]],"title":"FTC and Consumer Protection","uses":["Punishing deceptive advertising and billing.","Enforcing privacy promises.","Requiring security commensurate with claims."]},{"brief":"Employment law compliance covers hiring, wages, safety, leave, and anti-discrimination — the rules governing the employer-employee relationship.","examples":["A company classifies workers correctly after misclassification penalties in its industry.","HR documents performance issues consistently to support lawful terminations."],"history":["The Fair Labor Standards Act (1938), Civil Rights Act (1964), and FMLA (1993) built the framework.","State laws increasingly exceed federal minimums on wages, leave, and privacy."],"points":["Wage and hour: minimum wage, overtime, child labor, and proper classification (employee vs. contractor).","Anti-discrimination: protected classes in hiring, promotion, and termination — document decisions.","Leave: FMLA and state laws guarantee job-protected leave for family and medical reasons.","Posters, records, and training: the unglamorous backbone that proves compliance."],"qa":[["Employee vs. contractor?","Control over the work determines it — misclassification brings back taxes and penalties."],["What is at-will employment?","Either side may end the relationship anytime — limited by anti-discrimination and contract law."],["Which laws apply?","Federal plus every state (and city) of operation — the strictest applicable rule usually wins."]],"title":"Employment Law Compliance","uses":["Paying workers lawfully and fairly.","Preventing discrimination claims.","Managing leave and terminations correctly."]},{"brief":"Tax compliance means computing, reporting, and paying taxes correctly — income, payroll, sales, and international — with documentation to prove it.","examples":["A business files quarterly payroll returns and issues W-2s and 1099s on time.","A multinational documents transfer pricing between subsidiaries."],"history":["The modern income tax dates to 1913; complexity grew with every reform.","Digital reporting and e-filing in the 2000s-2010s raised the documentation bar."],"points":["Know your obligations: federal, state, local — income, payroll, sales, property, excise.","Payroll is the danger zone: trust-fund taxes carry personal liability for responsible persons.","Document everything: deductions, credits, and valuations need contemporaneous proof.","International: transfer pricing, reporting of foreign accounts, and treaty positions need specialist handling."],"qa":[["What is payroll trust-fund liability?","Withheld employee taxes belong to the government — responsible persons are personally liable."],["How long to keep records?","Generally 3-7 years depending on the tax and jurisdiction — longer for fraud or unfiled returns."],["When do I need a specialist?","Multi-state operations, international activity, or any IRS notice — early."]],"title":"Tax Compliance","uses":["Filing and paying correctly across jurisdictions.","Avoiding personal liability for payroll taxes.","Surviving audits with documentation."]},{"brief":"Export controls (ITAR/EAR) restrict sending sensitive technology, software, and data abroad — violations bring severe criminal penalties.","examples":["A company screens foreign hires' access to controlled technical data.","Encryption software needs classification before international distribution."],"history":["Cold War controls evolved into today's dual-use regimes; deemed exports extended rules to foreign nationals at home.","Enforcement intensified around semiconductors and advanced computing in the 2020s."],"points":["ITAR covers defense articles; EAR covers dual-use commercial technology — know which applies.","Deemed exports: sharing controlled technology with a foreign national domestically counts as exporting.","Screen customers, destinations, and end-uses against restricted-party and embargo lists.","Voluntary disclosure and compliance programs mitigate penalties when violations occur."],"qa":[["What is a deemed export?","Releasing controlled technology to a foreign national in the U.S. — legally an export."],["Who enforces?","State (ITAR), Commerce (EAR), Treasury (sanctions) — with criminal referral power."],["Do startups comply?","Yes — software, encryption, and technical data are all covered regardless of company size."]],"title":"Export Controls (ITAR/EAR)","uses":["Preventing sensitive technology reaching adversaries.","Screening hires, customers, and destinations.","Classifying products before international sales."]},{"brief":"Data retention policies define what data to keep, for how long, and how to destroy it — balancing legal duties against privacy and cost.","examples":["Financial records kept seven years per tax law; marketing data deleted after two.","Automatic deletion purges inactive accounts after the retention period."],"history":["Retention duties grew with regulation; privacy laws added the mirror duty to delete.","Litigation holds in the 2000s formalized suspending deletion during lawsuits."],"points":["Map each data type to its legal retention duty — tax, employment, health, financial each differ.","Set maximums too: privacy laws punish keeping data 'just in case' indefinitely.","Litigation holds override schedules: preserve everything relevant once litigation is anticipated.","Automate enforcement: manual deletion doesn't happen — systems must do it."],"qa":[["How long to keep data?","As long as law or business needs require, not a day longer — documented per category."],["What is a litigation hold?","A directive suspending routine deletion for anything relevant to actual or anticipated legal action."],["Can I keep everything?","Privacy laws say no — data minimization requires deleting what's no longer needed."]],"title":"Data Retention Policies","uses":["Meeting legal record-keeping duties.","Reducing breach impact by deleting unneeded data.","Defending deletion as routine, not suspicious."]},{"brief":"Privacy policies disclose what personal data an organization collects, why, and what rights individuals have — a legal requirement in most jurisdictions.","examples":["A policy lists data collected, purposes, retention, sharing, and how to exercise rights.","An app's just-in-time notice explains camera access when the feature is first used."],"history":["Policies became mandatory with early privacy laws; GDPR made them detailed and rights-focused.","The trend is layered notices: summaries up front, details one click away."],"points":["Disclose: what you collect, why, legal basis, retention, sharing, and individual rights with contact info.","Match practice to promise: the policy is enforceable — FTC and regulators punish gaps.","Update with every material change and notify users of significant ones.","Write for humans: layered, plain-language notices beat 40-page legalese nobody reads."],"qa":[["What must a policy contain?","Collection, purposes, sharing, retention, rights, contacts — per each applicable law's list."],["Are policies contracts?","Regulators treat them as enforceable promises — sometimes more binding than intended."],["How often to update?","With every new data practice, feature, or vendor — and review annually."]],"title":"Privacy Policies","uses":["Disclosing data practices as the law requires.","Building trust through transparency.","Creating the enforceable baseline regulators check."]},{"brief":"Terms of Service are the contract between a service and its users — acceptable use, liability limits, and dispute rules.","examples":["A platform's terms prohibit scraping and reserve content-moderation rights.","Arbitration clauses channel disputes out of court — where enforceable."],"history":["Browsewrap/clickwrap battles in the 2000s defined what makes online terms enforceable.","Consumer-protection scrutiny grew in the 2010s-2020s over unfair terms."],"points":["Cover: the service grant, acceptable use, IP, payments, liability caps, termination, and dispute resolution.","Enforceability needs notice and assent: conspicuous presentation plus a real 'I agree'.","Keep terms fair: one-sided terms invite regulatory action and user revolt.","Version and notify: material changes need user notice, sometimes fresh consent."],"qa":[["Are clickwrap terms enforceable?","Generally yes with clear notice and affirmative assent; hidden browsewrap often fails."],["What is an arbitration clause?","A term requiring disputes go to private arbitration — enforceability varies by jurisdiction."],["Can terms change anytime?","With proper notice for material changes; silent updates to key terms risk unenforceability."]],"title":"Terms of Service","uses":["Setting the legal rules of a service.","Limiting liability within legal bounds.","Reserving moderation and termination rights."]},{"brief":"Cookie consent rules require informing users about tracking technologies and obtaining consent before non-essential cookies.","examples":["A banner offers Accept/Reject with granular toggles per cookie purpose.","Strictly-necessary cookies run without consent; advertising cookies wait for opt-in."],"history":["The EU ePrivacy Directive (2002, 'cookie law') started it; GDPR raised the consent bar in 2018.","Enforcement waves fined dark patterns and pre-ticked boxes across Europe."],"points":["Consent must be freely given, specific, informed, and unambiguous — pre-ticked boxes don't count.","Strictly-necessary cookies are exempt; everything else waits for consent.","Reject must be as easy as accept — dark patterns draw fines.","Document consent: prove what each user chose, and honor withdrawals."],"qa":[["What is a dark pattern?","Design tricking users into consenting — hidden reject buttons, misleading wording — now fined."],["Do I need a banner?","If you use non-essential cookies for EU/UK users, yes — with real choice."],["What about cookie walls?","Forcing consent for access is largely prohibited — consent must be freely given."]],"title":"Cookie Consent","uses":["Complying with ePrivacy and GDPR tracking rules.","Giving users genuine choice over surveillance.","Documenting consent for regulators."]},{"brief":"Accessibility compliance (ADA, WCAG) requires digital products usable by people with disabilities — and it's increasingly enforced through lawsuits.","examples":["A site adds keyboard navigation, alt text, and captions to settle an accessibility suit.","WCAG 2.2 AA becomes the contractual standard in enterprise deals."],"history":["The ADA (1990) predates the web; courts extended it to websites in the 2010s.","Thousands of annual lawsuits made accessibility a legal priority, not just a nice-to-have."],"points":["WCAG 2.x AA is the practical standard: perceivable, operable, understandable, robust.","Common failures: missing alt text, keyboard traps, poor contrast, unlabeled forms, no captions.","Lawsuits target all sizes — small businesses included — often via serial plaintiffs.","Build it in: retrofitting accessibility costs far more than designing for it."],"qa":[["Does the ADA cover websites?","Courts increasingly say yes for places of public accommodation — the lawsuit wave assumes so."],["What is WCAG?","The Web Content Accessibility Guidelines — the technical standard for accessible web content."],["Where to start?","Automated scans plus keyboard-only testing catch most issues; screen-reader testing completes it."]],"title":"Accessibility (ADA/WCAG)","uses":["Avoiding lawsuits and opening markets to all users.","Meeting enterprise procurement requirements.","Building products usable by everyone."]},{"brief":"ESG (Environmental, Social, Governance) compliance covers sustainability disclosures, social responsibility, and governance standards — increasingly mandatory.","examples":["A company reports carbon emissions under new climate-disclosure rules.","Supply-chain due-diligence laws require human-rights risk mapping."],"history":["Voluntary ESG reporting grew in the 2010s; the 2020s brought mandatory regimes (EU CSRD).","Anti-greenwashing enforcement punishes empty sustainability claims."],"points":["Environmental: emissions, resource use, and climate risk disclosures.","Social: labor practices, human rights, diversity, and community impact.","Governance: board oversight, ethics, anti-corruption, and shareholder rights.","Disclosures must be assured and specific — vague green claims invite enforcement."],"qa":[["What is the CSRD?","The EU Corporate Sustainability Reporting Directive — mandatory detailed ESG disclosure for large companies."],["What is greenwashing?","Deceptive environmental claims — now fined by regulators on both sides of the Atlantic."],["Is ESG political?","The compliance duties are legal regardless of the cultural debate — disclose what's required, accurately."]],"title":"ESG (Environmental, Social, Governance)","uses":["Meeting mandatory sustainability disclosure laws.","Satisfying investor and customer ESG demands.","Managing climate and social risks systematically."]},{"brief":"Audit trails are chronological records of system and user activity — who did what, when — the evidence backbone of compliance.","examples":["Financial systems log every journal entry with user, timestamp, and before/after values.","A security team reconstructs a breach timeline from authentication logs."],"history":["Audit trails grew with computerized accounting; SOX made them mandatory for financial systems.","Tamper-evident logging (hash chains, WORM storage) answered the 'who watches the logs' problem."],"points":["Capture: who, what, when, where — complete enough to reconstruct any event.","Protect: append-only, tamper-evident storage — editable logs prove nothing.","Retain per legal duties; review regularly — unreviewed logs are decoration.","Cover privileged actions most: admin changes deserve the closest scrutiny."],"qa":[["What makes a log an audit trail?","Completeness, accuracy, and tamper-resistance — enough to reconstruct events reliably."],["How long to keep trails?","Per legal duties (often years) — financial and security logs have specific minimums."],["What is WORM storage?","Write Once, Read Many — physically preventing alteration or premature deletion."]],"title":"Audit Trails","uses":["Proving what happened during audits and investigations.","Reconstructing security incidents.","Demonstrating control operation to regulators."]},{"brief":"Whistleblower protections shield employees who report wrongdoing — with anti-retaliation laws and reward programs that make internal reporting work.","examples":["An employee reports accounting fraud through the ethics hotline without retaliation.","SEC whistleblower awards reach tens of millions for original information."],"history":["SOX (2002) added corporate whistleblower protections; Dodd-Frank (2010) created SEC bounty programs.","The EU Whistleblower Directive (2019) mandated reporting channels across member states."],"points":["Protect: retaliation for good-faith reporting is illegal — termination, demotion, harassment.","Channel: confidential reporting mechanisms (hotlines, web forms) that employees trust.","Investigate promptly and document: every report gets a fair, recorded review.","Reward programs (SEC, IRS) pay for original information leading to successful enforcement."],"qa":[["What counts as retaliation?","Any adverse action for reporting — firing, demotion, threats, or blacklisting."],["Must reports be anonymous?","Systems should allow it; investigations proceed on facts regardless."],["What makes a hotline trusted?","Independence, confidentiality, visible follow-through — and no retaliation, ever."]],"title":"Whistleblower Protections","uses":["Surfacing fraud and misconduct early.","Earning regulatory credit for effective programs.","Protecting reporters from retaliation."]},{"brief":"Incident response is the organized capability to detect, contain, eradicate, and recover from security and compliance incidents.","examples":["A ransomware attack triggers the IR plan: isolate, engage counsel, restore from backups.","A tabletop exercise reveals the call tree is outdated — fixed before a real crisis."],"history":["CERT (1988, after the Morris worm) pioneered organized response.","NIST SP 800-61 standardized the preparation-detection-containment-eradication-recovery-lessons cycle."],"points":["Plan before crisis: roles, call trees, playbooks, and legal/communications coordination.","Contain first: stop the bleeding (isolate systems) before investigating root cause.","Preserve evidence: forensic images before rebuilding — investigations need intact data.","Learn always: post-incident reviews turn each crisis into stronger defenses."],"qa":[["What is a tabletop exercise?","A simulated incident walkthrough testing the plan and people without real damage."],["When to call counsel?","Early — privilege protects the investigation, and breach laws have tight clocks."],["What is containment?","Limiting the incident's spread: isolating hosts, revoking credentials, blocking indicators."]],"title":"Incident Response","uses":["Minimizing damage from breaches and outages.","Meeting breach-notification deadlines.","Turning incidents into institutional learning."]},{"brief":"Breach notification laws require telling regulators and affected individuals about data breaches — quickly, with specific content, on strict deadlines.","examples":["A company notifies state attorneys general within 60 days of discovering exposed customer data.","GDPR's 72-hour clock starts when the company becomes aware of the breach."],"history":["California's 2003 breach law started the wave; all 50 states now have one.","GDPR (2018) added the 72-hour regulatory deadline with massive fines."],"points":["Triggers: unauthorized acquisition of personal information — definitions vary by state.","Deadlines: from 72 hours (GDPR, to regulators) to 30-90 days (individuals, by state).","Content: what happened, what data, what you're doing, what individuals should do.","Delays allowed for law-enforcement investigations — document the reason."],"qa":[["When does the clock start?","When the organization becomes aware of the breach — not when it occurred."],["Who must be notified?","Affected individuals, regulators, and sometimes credit bureaus and media — per each law."],["What if we had good encryption?","Many laws exempt properly encrypted data — another reason to encrypt."]],"title":"Breach Notification Laws","uses":["Meeting legal deadlines after breaches.","Preserving trust through prompt disclosure.","Avoiding the fines that follow late notice."]},{"brief":"Risk assessments systematically identify, analyze, and prioritize compliance and security risks — the foundation every program is built on.","examples":["A privacy impact assessment maps data flows before launching a new product.","An annual enterprise risk assessment ranks regulatory, cyber, and operational risks."],"history":["Risk assessment matured with 1990s operational-risk management; privacy impact assessments became law under GDPR.","NIST SP 800-30 standardized the security assessment method."],"points":["Process: identify assets and threats, assess likelihood and impact, prioritize, treat, and monitor.","Document everything: the assessment is the evidence that diligence was exercised.","Reassess on change: new products, vendors, laws, and incidents all trigger updates.","Risk appetite — how much risk leadership accepts — guides which risks get treated."],"qa":[["What is a DPIA?","A Data Protection Impact Assessment — required under GDPR for high-risk processing."],["Qualitative vs. quantitative?","Qualitative ranks high/medium/low; quantitative models dollars — use both where each fits."],["How often?","Annually at minimum, plus whenever things change materially."]],"title":"Risk Assessments","uses":["Focusing compliance effort where risk is highest.","Satisfying regulatory assessment duties.","Justifying security investments with analysis."]},{"brief":"Internal controls are the policies and procedures ensuring operations are effective, reporting reliable, and laws followed — the machinery of compliance.","examples":["Purchase orders over $10,000 need two approvals.","Monthly bank reconciliations catch errors before reports go out."],"history":["COSO's 1992 framework defined internal control; SOX 404 (2002) made it auditable at public companies.","COSO's 2013 update modernized for technology and outsourcing."],"points":["Five COSO components: control environment, risk assessment, control activities, information/communication, monitoring.","Preventive controls stop problems; detective controls find them — use both.","Automate where possible: system-enforced controls beat policy documents.","Test operating effectiveness: a control that isn't followed is decoration."],"qa":[["What is COSO?","The Committee of Sponsoring Organizations framework — the standard model of internal control."],["Preventive vs. detective?","Preventive blocks bad acts (approvals); detective finds them after (reconciliations)."],["Who tests controls?","Management first, then internal audit, then external auditors for SOX."]],"title":"Internal Controls","uses":["Ensuring reliable financial reporting.","Preventing and detecting fraud.","Proving control operation to auditors."]},{"brief":"Compliance training teaches employees the rules that apply to their roles — and documents that the organization taught them.","examples":["Annual anti-harassment training for all managers, tracked to completion.","Role-based privacy training for engineers handling personal data."],"history":["Sentencing guidelines (1991) rewarded 'effective' programs including training.","E-learning in the 2000s made annual training scalable; regulators now expect proof of completion."],"points":["Target by role: everyone gets basics; high-risk roles get deep, specific training.","Make it stick: scenarios and short modules beat annual click-through marathons.","Track completion: regulators ask for records — untracked training didn't happen.","Refresh on change: new laws, new risks, and incidents all trigger updates."],"qa":[["How often?","Annually at minimum for core topics; more often for high-risk roles."],["Does training reduce liability?","Yes — effective programs earn sentencing credit and show good faith."],["What makes training effective?","Relevance to the learner's actual decisions, not generic legal lectures."]],"title":"Compliance Training","uses":["Teaching employees the rules for their roles.","Documenting diligence for regulators.","Reducing violations through awareness."]},{"brief":"Vendor compliance ensures third parties handling your data or operations meet your regulatory obligations — their failure is your breach.","examples":["A company requires SOC 2 reports from every SaaS vendor touching customer data.","A manufacturer audits suppliers' labor practices under supply-chain laws."],"history":["Outsourcing booms made vendor risk a top concern; breach headlines traced to vendors accelerated requirements.","Supply-chain due-diligence laws in the 2020s formalized the duty."],"points":["Inventory vendors by risk: what data/access they have determines the scrutiny.","Contract the duties: security, breach notice, audit rights, and return/deletion of data.","Verify continuously: questionnaires, certifications, and audits — not just at signing.","Plan exits: how data returns and is deleted when the relationship ends."],"qa":[["What is fourth-party risk?","Your vendors' vendors — the extended chain where visibility fades."],["Which vendors matter most?","Those with your data, your customers, or your critical operations."],["What goes in the contract?","Security duties, breach notification, audit rights, data handling, and termination terms."]],"title":"Vendor Compliance","uses":["Extending compliance to the supply chain.","Preventing vendor-caused breaches.","Meeting due-diligence legal duties."]},{"brief":"Third-party risk management is the lifecycle of governing external relationships — from selection through monitoring to exit.","examples":["A bank scores fintech partners on security before integration.","Continuous monitoring flags a vendor's deteriorating security posture mid-contract."],"history":["TPRM matured with outsourcing in the 2000s; regulators (OCC 2013) made it an examined discipline.","The 2020s added concentration and fourth-party risk to the scope."],"points":["Lifecycle: plan, due diligence, contract, ongoing monitoring, termination.","Risk-tier vendors: critical partners get deep reviews; low-risk get light touch.","Monitor continuously: security ratings, financial health, and compliance attestations.","Have exit plans: concentration in one vendor is its own risk."],"qa":[["TPRM vs. vendor compliance?","TPRM is the full lifecycle discipline; vendor compliance is meeting specific regulatory duties within it."],["What is concentration risk?","Over-dependence on one vendor — their failure becomes your failure."],["How deep should diligence go?","Proportional to the risk the third party poses — tiered, not one-size-fits-all."]],"title":"Third-Party Risk Management","uses":["Governing outsourcing risk systematically.","Satisfying regulator expectations for vendor oversight.","Planning for vendor failure or exit."]},{"brief":"Contract compliance means meeting — and enforcing — contractual obligations: deliverables, SLAs, payment terms, and regulatory clauses.","examples":["A team tracks SLA credits owed when a vendor misses uptime targets.","A license audit verifies the company stays within its software entitlements."],"history":["Contract management professionalized with enterprise software in the 2000s.","AI contract review in the 2010s-2020s automated obligation extraction."],"points":["Know your obligations: extract key terms — dates, deliverables, penalties — into trackable form.","Monitor performance against SLAs and milestones; claim remedies when missed.","Manage renewals: auto-renewals and price escalations need calendar discipline.","Flow down regulatory duties: vendors' contracts must carry your compliance requirements."],"qa":[["What is contract lifecycle management?","The discipline from request through drafting, execution, performance, and renewal/termination."],["Why do contracts fail?","Signed and forgotten — obligations need owners and tracking, not just signatures."],["What is a flow-down clause?","Requiring your vendor to impose your regulatory duties on their subcontractors."]],"title":"Contract Compliance","uses":["Meeting contractual deliverables and SLAs.","Enforcing vendor performance.","Managing renewals and obligations proactively."]},{"brief":"Intellectual property compliance protects creations — patents, trademarks, copyrights, trade secrets — and respects others' rights.","examples":["An engineering team runs open-source license scans before each release.","A brand polices trademark use and registers marks in key markets."],"history":["IP regimes are centuries old; the digital age made copyright and trade-secret compliance daily engineering concerns.","Trade-secret protection rose as employee mobility increased."],"points":["Identify what you own: inventions, brands, content, secrets — and protect each appropriately.","Respect others': license software properly, clear content rights, avoid infringement.","Trade secrets need reasonable measures: NDAs, access controls, and exit procedures.","Police your rights: trademarks weaken without enforcement; patents need maintenance."],"qa":[["What is a trade secret?","Confidential business information with economic value, protected by reasonable secrecy measures."],["How do I avoid infringement?","Clearance searches, licensed assets, and engineering practices that don't copy competitors' code."],["What is an NDA?","A non-disclosure agreement binding recipients to keep shared secrets confidential."]],"title":"Intellectual Property Compliance","uses":["Protecting innovations, brands, and secrets.","Avoiding infringement lawsuits.","Monetizing IP through licensing."]},{"brief":"Records management governs business records' lifecycle — creation, classification, retention, and destruction — per legal and business needs.","examples":["A retention schedule keeps contracts seven years and resumes one year.","Legal holds suspend destruction for litigation-relevant records."],"history":["Paper records management is ancient; electronic records rules matured with 2000s regulations.","Information governance now unifies records, privacy, and security."],"points":["Classify records by type and assign retention per legal duty — the schedule is the core artifact.","Apply consistently: selective retention looks like spoliation in litigation.","Destroy on schedule: keeping everything increases breach and discovery costs.","Electronic records need the same discipline as paper — plus format and readability planning."],"qa":[["What is a retention schedule?","The table mapping each record type to its retention period and disposition."],["What is spoliation?","Destroying relevant records during litigation — sanctionable, sometimes case-losing."],["Do emails count as records?","If they document business decisions, yes — email is the biggest records challenge."]],"title":"Records Management","uses":["Meeting legal record-keeping duties.","Controlling discovery costs in litigation.","Deleting what should be deleted, on time."]},{"brief":"E-discovery is the process of finding, preserving, and producing electronic evidence for litigation — with strict duties and high stakes.","examples":["A litigation hold preserves 50 custodians' emails within 24 hours of a lawsuit.","Technology-assisted review prioritizes 2 million documents for attorney review."],"history":["E-discovery rules entered U.S. federal procedure in 2006; predictive coding gained acceptance in the 2010s.","Proportionality now limits fishing expeditions into massive data stores."],"points":["Preserve first: litigation holds must issue immediately and reach all custodians including mobile and cloud.","Collect defensibly: forensically sound methods with chain of custody.","Review efficiently: keyword, concept, and AI-assisted review tame volume.","Produce in agreed formats with privilege logs for withheld documents."],"qa":[["What triggers preservation?","Reasonable anticipation of litigation — earlier than many expect."],["What is a custodian?","A person whose data may be relevant — employees, executives, sometimes vendors."],["What is predictive coding?","AI trained on attorney decisions prioritizing likely-relevant documents — court-accepted when validated."]],"title":"E-Discovery","uses":["Meeting evidence duties in litigation.","Controlling the cost of massive document review.","Avoiding sanctions for spoliation."]},{"brief":"Sanctions compliance (OFAC) prohibits business with sanctioned countries, entities, and individuals — with strict liability and massive penalties.","examples":["A bank blocks a wire to a sanctioned entity flagged by screening software.","A company maps its supply chain to avoid sanctioned-region components."],"history":["OFAC administers sanctions since 1950; post-9/11 programs expanded dramatically.","Multi-billion-dollar settlements in the 2010s made sanctions a board issue."],"points":["Screen customers, vendors, and transactions against SDN and restricted lists — continuously, not once.","Strict liability: violations punishable even without intent — the compliance program is the defense.","50% rule: entities owned 50%+ by sanctioned parties are sanctioned too.","Voluntary disclosure and cooperation mitigate penalties significantly."],"qa":[["What is the SDN list?","OFAC's Specially Designated Nationals list — doing business with listed parties is prohibited."],["What is strict liability?","Liability without proving intent — a paperwork failure can still draw penalties."],["Do sanctions apply extraterritorially?","U.S. sanctions reach foreign subsidiaries and dollar transactions worldwide."]],"title":"Sanctions Compliance (OFAC)","uses":["Blocking prohibited transactions automatically.","Screening supply chains for sanctioned parties.","Disclosing violations to mitigate penalties."]},{"brief":"Anti-bribery programs go beyond the FCPA — covering the UK Bribery Act, local laws, and commercial bribery — with controls that actually prevent payoffs.","examples":["A gifts-and-entertainment policy requires pre-approval above $100.","Due diligence vets intermediaries before any engagement."],"history":["The UK Bribery Act (2010) went further than the FCPA, covering commercial bribery and demanding 'adequate procedures'.","Global enforcement cooperation now shares evidence across borders routinely."],"points":["Risk-assess markets and interactions: government touchpoints are the highest risk.","Control the channels: gifts, travel, donations, and intermediaries need approvals and records.","Train the exposed: sales, procurement, and local staff get specific, scenario-based training.","Investigate and remediate: every allegation gets a documented, independent review."],"qa":[["UK Bribery Act vs. FCPA?","Broader: covers commercial bribery, no facilitating-payments exception, and corporate liability without 'adequate procedures'."],["What are adequate procedures?","Proportionate anti-bribery controls — the defense against corporate liability under the UK Act."],["Why vet intermediaries?","Because most bribery flows through agents and partners — their conduct is your liability."]],"title":"Anti-Bribery Programs","uses":["Preventing corruption in high-risk markets.","Satisfying multi-jurisdiction anti-bribery laws.","Vetting intermediaries before engagement."]},{"brief":"Consumer protection laws guard buyers against deception, unfair practices, and unsafe products — enforced by the FTC, states, and the CFPB.","examples":["State attorneys general sue over hidden subscription renewals.","The CFPB polices unfair practices in consumer finance."],"history":["State UDAP laws and the FTC Act built the framework; Dodd-Frank (2010) created the CFPB.","Subscription and dark-pattern enforcement surged in the 2020s."],"points":["UDAP: unfair or deceptive acts and practices — the core prohibition in every state.","Disclose clearly: pricing, renewals, and material terms before the consumer commits.","Product safety: report defects and recall promptly — the CPSC enforces.","State laws often exceed federal: know every state where you sell."],"qa":[["What is a UDAP law?","State Unfair and Deceptive Acts and Practices statutes — the state-level FTC Acts."],["What is the CFPB?","The Consumer Financial Protection Bureau — policing banks, lenders, and financial products."],["What are dark patterns?","Interfaces manipulating users into unintended choices — now an enforcement priority."]],"title":"Consumer Protection Laws","uses":["Marketing honestly and disclosing clearly.","Handling subscriptions and renewals fairly.","Recalling unsafe products promptly."]},{"brief":"Financial regulations (Dodd-Frank and successors) govern banks, markets, and consumer finance — capital, conduct, and systemic risk.","examples":["Stress tests prove big banks survive economic shocks.","Swap dealers register and report derivatives trades."],"history":["Dodd-Frank (2010) answered the 2008 crisis; later laws tailored rules by bank size.","Crypto and fintech brought new perimeters in the 2020s."],"points":["Prudential: capital, liquidity, and stress testing keep banks solvent.","Conduct: fair treatment of consumers and markets — no manipulation, no deception.","Reporting: derivatives, large positions, and suspicious activity all get reported.","The perimeter keeps moving: new products attract new rules — watch fintech and crypto."],"qa":[["What is a stress test?","A regulatory exercise proving a bank stays solvent through severe economic scenarios."],["What is the Volcker Rule?","Dodd-Frank’s ban on proprietary trading by banks — they cannot gamble with deposits."],["Does Dodd-Frank cover crypto?","Not directly as written, but regulators apply its principles and newer crypto rules build on its framework."]],"title":"Financial Regulations (Dodd-Frank)","uses":["Keeping banks safe through capital and stress tests.","Policing market manipulation and consumer abuse.","Adapting compliance as products evolve."]},{"brief":"Telecommunications compliance (FCC) governs carriers, broadcasters, and now broadband — licensing, robocalls, and emergency services.","examples":["A carrier implements STIR/SHAKEN to authenticate caller ID against spoofing.","A broadcaster meets children's programming and political-file obligations."],"history":["The Communications Act (1934) created the FCC; the 1996 Act opened competition.","Robocall wars of the 2010s-2020s drove STIR/SHAKEN mandates."],"points":["Licensing: spectrum and broadcast licenses carry build-out and content duties.","Robocalls: consent required; STIR/SHAKEN authenticates caller ID.","E911: carriers must deliver location with emergency calls.","Net neutrality rules have seesawed — track the current regime."],"qa":[["What is STIR/SHAKEN?","The caller-ID authentication framework fighting robocall spoofing."],["Do robocall rules apply to texts?","Yes — the TCPA covers calls and texts with consent and opt-out duties."],["What is E911?","Enhanced 911: location data delivered with emergency calls, including from mobile and VoIP."]],"title":"Telecommunications Compliance (FCC)","uses":["Stopping illegal robocalls.","Licensing spectrum and broadcast operations.","Ensuring emergency-call reliability."]},{"brief":"Food safety compliance (FSMA) requires preventing contamination — hazard analysis, preventive controls, and traceability across the supply chain.","examples":["A produce farm implements water-testing and worker-hygiene controls.","A manufacturer traces a contaminated lot to specific suppliers within hours."],"history":["The 1906 Pure Food and Drug Act started it; FSMA (2011) shifted the focus to prevention.","Traceability rules in the 2020s answered outbreak-investigation failures."],"points":["Preventive controls: analyze hazards and control them — the HARPC approach.","Supply-chain programs verify suppliers' controls, not just their promises.","Traceability: know where each lot came from and went — fast.","Inspections and records prove the system works; the FDA can suspend facilities."],"qa":[["What is HARPC?","Hazard Analysis and Risk-Based Preventive Controls — the FSMA food-safety system."],["What changed with FSMA?","From reacting to contamination to preventing it — with verification teeth."],["Who is covered?","Farms, facilities, importers, and transporters — most of the food chain."]],"title":"Food Safety (FSMA)","uses":["Preventing foodborne illness through controls.","Tracing contamination to sources fast.","Verifying supplier food-safety practices."]},{"brief":"Transportation compliance (DOT) governs carriers, drivers, vehicles, and hazardous materials — safety rules for moving goods and people.","examples":["Trucking companies track hours-of-service electronically to prevent fatigued driving.","Hazmat shippers classify, package, and placard dangerous goods per regulations."],"history":["The DOT was created in 1966; motor-carrier safety rules evolved with the interstate system.","Electronic logging devices (2017) ended paper logbooks' fiction."],"points":["Hours of service limit driving time — now tracked by tamper-resistant ELDs.","Vehicle standards: inspections, maintenance records, and driver qualification files.","Hazmat: classification, packaging, labeling, and training — with severe penalties.","Operating authority and insurance minimums gate market entry."],"qa":[["What is an ELD?","Electronic Logging Device — automatically recording driving time, replacing paper logs."],["What is hazmat?","Hazardous materials: regulated from classification through packaging to emergency response."],["Who needs operating authority?","For-hire carriers of passengers or interstate freight — the DOT number system."]],"title":"Transportation Compliance (DOT)","uses":["Preventing fatigued-driving crashes.","Moving hazardous materials safely.","Qualifying carriers and drivers."]},{"brief":"Building codes and permits ensure structures are safe, accessible, and lawful — the compliance layer of construction.","examples":["A renovation needs permits, inspections, and a certificate of occupancy.","Fire codes dictate egress, alarms, and sprinklers by occupancy type."],"history":["Great fires drove early codes; the International Building Code (2000) unified U.S. practice.","Energy and accessibility provisions grew in the 2000s-2010s."],"points":["Permits authorize work; inspections verify it; certificates of occupancy legalize use.","Codes cover structure, fire, electrical, plumbing, mechanical, and energy.","Zoning governs what can be built where — use, height, setbacks, parking.","Build without permits and you may tear it out — plus fines."],"qa":[["What is a certificate of occupancy?","The approval that a building is safe and legal to occupy."],["Who enforces codes?","Local building departments through plan review and field inspections."],["What is zoning?","Local law governing land use — what's allowed where."]],"title":"Building Codes and Permits","uses":["Ensuring buildings are structurally and fire safe.","Legalizing construction through permits.","Governing land use through zoning."]},{"brief":"Insurance compliance covers licensing, solvency, claims handling, and market conduct for insurers — plus policyholders' duties.","examples":["An insurer maintains risk-based capital above regulatory minimums.","A business carries the workers' comp and liability coverage its contracts require."],"history":["State-based regulation dates to the 1800s; the NAIC coordinates standards.","Solvency regimes modernized after insurer failures."],"points":["Insurers: licensed in each state of operation, with capital adequacy and claims-handling standards.","Market conduct exams police sales practices and claims fairness.","Policyholders: maintain required coverages and report claims promptly.","Reinsurance and guaranty funds backstop catastrophic failures."],"qa":[["Who regulates insurance?","Primarily states in the U.S. — each with its own commissioner and rules."],["What is risk-based capital?","The capital formula ensuring insurers can pay claims in adverse scenarios."],["What is market conduct?","Fair treatment of policyholders in sales, underwriting, and claims."]],"title":"Insurance Compliance","uses":["Keeping insurers solvent and fair.","Meeting contractual insurance requirements.","Protecting policyholders through conduct rules."]},{"brief":"The future of compliance is continuous, automated, and predictive — real-time monitoring, AI-assisted review, and regulation that updates as fast as business.","examples":["Continuous controls monitoring flags exceptions daily instead of annually.","AI reviews contracts and flags risky clauses before signing."],"history":["Compliance moved from annual audits to continuous assurance through the 2010s-2020s.","RegTech grew into a multi-billion-dollar industry automating the work."],"points":["Continuous assurance replaces point-in-time audits: always-on monitoring of controls.","AI assists — never replaces — judgment: flagging anomalies for human review.","Regulation is accelerating: privacy, AI, and ESG rules multiply across jurisdictions.","The constant: document, monitor, improve — the tools change, the discipline doesn't."],"qa":[["What is RegTech?","Technology automating compliance: monitoring, reporting, screening, and training."],["Will AI replace compliance officers?","No — it scales their reach; accountability and judgment stay human."],["What's the biggest coming wave?","AI regulation itself — governing the systems now assisting compliance."]],"title":"The Future of Compliance","uses":["Planning for continuous, automated assurance.","Adopting AI assistance with human oversight.","Tracking the expanding regulatory frontier."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief+' This '+angle+' guide provides comprehensive coverage.',genre:angle,type:RECORD_KIND,content:content,demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-compliance-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('compliance',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();